import java.util.*;

class AutocompleteSystem {
    private static final int K = 3;

    private static class TrieNode {
        Map<Character, TrieNode> children = new HashMap<>();
        // Top-K sentences in the subtree, kept sorted by rank rule.
        List<String> hot = new ArrayList<>();
    }

    private final TrieNode root = new TrieNode();
    private final Map<String, Integer> freq = new HashMap<>();
    private StringBuilder current = new StringBuilder();
    private TrieNode cursor;

    public AutocompleteSystem(String[] sentences, int[] times) {
        cursor = root;
        for (int i = 0; i < sentences.length; i++) {
            addSentence(sentences[i], times[i]);
        }
    }

    public List<String> input(char c) {
        if (c == '#') {
            addSentence(current.toString(), 1);
            current = new StringBuilder();
            cursor = root;
            return Collections.emptyList();
        }
        current.append(c);
        if (cursor != null) {
            cursor = cursor.children.get(c);
        }
        if (cursor == null) return Collections.emptyList();
        return new ArrayList<>(cursor.hot);
    }

    private void addSentence(String s, int delta) {
        if (s.isEmpty()) return; // '#' on empty prefix records nothing
        freq.put(s, freq.getOrDefault(s, 0) + delta);
        TrieNode node = root;
        for (char ch : s.toCharArray()) {
            node = node.children.computeIfAbsent(ch, k -> new TrieNode());
            refresh(node, s);
        }
    }

    private void refresh(TrieNode node, String s) {
        if (!node.hot.contains(s)) node.hot.add(s);
        node.hot.sort((a, b) -> {
            int fa = freq.get(a), fb = freq.get(b);
            if (fa != fb) return Integer.compare(fb, fa); // hotter first
            return a.compareTo(b);                        // lexicographic tie-break
        });
        if (node.hot.size() > K) node.hot.remove(node.hot.size() - 1);
    }
}

class _Node:
    __slots__ = ("children", "hot")
    def __init__(self):
        self.children = {}
        self.hot = []  # top-3 sentences in subtree, ranked

class AutocompleteSystem:
    K = 3
    def __init__(self, sentences, times):
        self.root = _Node()
        self.freq = {}
        self.cur = []
        self.cursor = self.root
        for s, t in zip(sentences, times):
            self._add(s, t)

    def input(self, c: str):
        if c == "#":
            self._add("".join(self.cur), 1)
            self.cur = []
            self.cursor = self.root
            return []
        self.cur.append(c)
        if self.cursor is not None:
            self.cursor = self.cursor.children.get(c)
        return list(self.cursor.hot) if self.cursor else []

    def _add(self, s: str, delta: int):
        if not s:
            return
        self.freq[s] = self.freq.get(s, 0) + delta
        node = self.root
        for ch in s:
            node = node.children.setdefault(ch, _Node())
            if s not in node.hot:
                node.hot.append(s)
            node.hot.sort(key=lambda x: (-self.freq[x], x))
            del node.hot[self.K:]
